                        fieldId="action-command"
                        fullWidth
                        helperText={errors.command}
                        label="Command"
                        minRows={2}
                        multiline
                        name="command"
                        onChange={handleRequiredTextChange}
                        source={definition}
                        value={definition.command ?? ''}
                    />
                )}
                <Divider />
